endpoints.typescript_example:
// Partner laboratories and imaging centres  (permissions: diagnostics.setup.manage, diagnostics.quality.view, lab.sendout.manage, imaging.order.update, lab.test.manage)
export const listPartners = () =>
  api("GET", `/diagnostic-partners`, undefined);   // api(): see get_guide('envelope-and-errors')

// Send an examination to a partner centre  (permissions: imaging.order.update)
export const outsource = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/outsource`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Enter the partner centre's report  (permissions: imaging.order.update)
export const externalReport = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/external-report`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Radiographer worklist (STAT first, then by due time)  (permissions: imaging.order.update)
export const worklistImaging = () =>
  api("GET", `/imaging/worklist`, undefined);   // api(): see get_guide('envelope-and-errors')

